const body = $json.body || $json;

function boolish(v) {
  return (
    v === true ||
    v === 1 ||
    String(v || '').trim().toLowerCase() === 'true' ||
    String(v || '').trim().toLowerCase() === 'yes' ||
    String(v || '').trim().toLowerCase() === '1'
  );
}

return [{
  json: {
    mode: String(body.mode || 'all').toLowerCase(),
    date: String(body.date || ''),
    timezone: String(body.timezone || 'America/Denver'),
    include_review: boolish(body.include_review)
  }
}];

const req = $('Code - Parse List Request').first().json;
const rows = Array.isArray($json.records) ? $json.records : [];

function zonedParts(v, tz) {
  if (!v) return null;
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return null;

  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: tz,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  }).formatToParts(d);

  return Object.fromEntries(parts.map(p => [p.type, p.value]));
}

function dateKey(v, tz) {
  const m = zonedParts(v, tz);
  if (!m) return '';
  return `${m.year}-${m.month}-${m.day}`;
}

function localDateTime(v, tz) {
  if (!v) return '';
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return '';
  return new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: 'numeric',
    minute: '2-digit',
    second: '2-digit',
    hour12: true
  }).format(d);
}

function parseItems(s) {
  try {
    const a = typeof s === 'string' ? JSON.parse(s) : [];
    return Array.isArray(a) ? a : [];
  } catch (e) {
    return [];
  }
}

function itemSummary(items) {
  return items
    .map(i => `${i.name || i.nameTranslated?.en || '(unknown)'} x${Number(i.quantity || 0) || 0}`)
    .join(', ');
}

/*
  IMPORTANT:
  Treat requested date as a plain calendar date, not a moment in time.
  Do not convert it through Date()/timezone math.
*/
function normalizeReqDate(v) {
  const s = String(v || '').trim();
  if (!s) return '';

  const m = s.match(/^(\d{4}-\d{2}-\d{2})/);
  return m ? m[1] : '';
}

const mode = String(req.mode || 'all');
const timezone = req.timezone || 'America/Denver';
const reqDateRaw = req.date || '';
const reqDate = normalizeReqDate(reqDateRaw);

const out = [];
const debug = [];

for (const rec of rows) {
  const f = rec.fields || {};
  const items = parseItems(f.items_json);

  const requiredCount = items.reduce(
    (n, i) => n + (Number(i.quantity || 0) || 0),
    0
  );

  const linkedProducts = Array.isArray(f.products) ? f.products : [];
  const linkedCount = linkedProducts.length;
  const progress = f.fulfillment_progress || {};
  const productAssignmentComplete = progress.product_assignment_complete ?? (requiredCount > 0 && linkedCount >= requiredCount);

  const paymentMethod = String(f.payment_method || '');
  const salesChannel = String(f.provider || 'ecwid').trim().toLowerCase() || 'ecwid';
  const legacyMarket = String(paymentMethod || '').startsWith('Sell on the Go');
  const market = legacyMarket || ['moov_pos', 'clover_pos', 'market'].includes(salesChannel);

  // Prefer the provider-neutral payment aliases introduced by Issue #85 R1.
  // Fall back to Clover fields so the Airtable compatibility workflow and
  // pre-R1 records continue to behave identically during migration.
  const legacyCloverEvidence = Boolean(
    legacyMarket ||
    f.clover_payment_id ||
    f.clover_payment_amount ||
    f.clover_payment_time ||
    f.clover_match_confidence
  );
  const paymentProcessor = String(
    f.payment_processor || (legacyCloverEvidence ? 'clover' : '')
  ).toLowerCase();
  const reconciliationStatus = String(
    f.payment_reconciliation_status || f.clover_reconciliation_status || ''
  ).toLowerCase();
  const processorPaymentId =
    f.processor_payment_id ||
    (paymentProcessor === 'clover' ? f.clover_payment_id : null) ||
    null;
  const processorPaymentStatus = String(f.processor_payment_status || '');
  const processorPaymentAmount =
    f.processor_payment_amount ??
    (paymentProcessor === 'clover' ? f.clover_payment_amount : null) ??
    null;
  const processorPaymentTime =
    f.processor_payment_time ||
    (paymentProcessor === 'clover' ? f.clover_payment_time : null) ||
    null;
  const processorMatchConfidence =
    f.processor_match_confidence ??
    (paymentProcessor === 'clover' ? f.clover_match_confidence : null) ??
    null;
  const paymentStatus = String(f.payment_status || '').toUpperCase();

  const includeReview =
    req.include_review === true ||
    String(req.include_review || '').toLowerCase() === 'true';

  const accounted = reconciliationStatus === 'accounted';
  const requiresProcessorReconciliation = Boolean(
    market ||
    (paymentProcessor && paymentProcessor !== 'cash' && reconciliationStatus)
  );

  const reviewable =
    requiresProcessorReconciliation &&
    ['pending', 'needs_review'].includes(reconciliationStatus);

  const marketCash = market && paymentMethod === 'Sell on the Go - Cash';
  const cashWeb = !market && ['cash','pay by cash','pay with cash','cash on delivery','cod'].includes(paymentMethod.trim().toLowerCase());
  const cashOpen = cashWeb && !['SHIPPED','DELIVERED','WILL_NOT_DELIVER','RETURNED','CANCELLED'].includes(String(f.status||'').toUpperCase());

  const ready = cashOpen ? true : marketCash
    ? (paymentStatus === 'PAID' || accounted)
    : requiresProcessorReconciliation
      ? (reconciliationStatus === 'reconciled' || accounted)
      : paymentStatus === 'PAID';

  const reconciliationComplete = requiresProcessorReconciliation
    ? (reconciliationStatus === 'reconciled' || accounted)
    : paymentStatus === 'PAID';
  const assignmentCompleteNeedsReconciliation =
    productAssignmentComplete && requiresProcessorReconciliation && !reconciliationComplete;
  const fullyComplete = productAssignmentComplete && reconciliationComplete;

  const rowDate = dateKey(f.order_date, timezone);

  let excludedBy = null;

  if (mode === 'market' && !market) {
    excludedBy = 'mode_market';
  } else if (mode === 'web' && market) {
    excludedBy = 'mode_web';
  } else if (!ready && !assignmentCompleteNeedsReconciliation && !(includeReview && reviewable)) {
    excludedBy = 'not_ready';
  } else if (reqDate && rowDate !== reqDate) {
    excludedBy = 'date';
  }

  debug.push({
    id: rec.id,
    order_code: f.order_code || null,
    payment_method: paymentMethod,
    sales_channel: salesChannel,
    market,
    legacy_market: legacyMarket,
    requires_processor_reconciliation: requiresProcessorReconciliation,
    payment_status: f.payment_status || null,
    payment_processor: paymentProcessor || null,
    payment_reconciliation_status: reconciliationStatus || null,
    processor_payment_id: processorPaymentId,
    clover_reconciliation_status: f.clover_reconciliation_status || null,
    order_date_raw: f.order_date || null,
    row_date: rowDate,
    req_date_raw: reqDateRaw || null,
    req_date: reqDate || null,
    linked_count: linkedCount,
    required_count: requiredCount,
    product_assignment_complete: productAssignmentComplete,
    reconciliation_complete: reconciliationComplete,
    assignment_complete_needs_reconciliation: assignmentCompleteNeedsReconciliation,
    fully_complete: fullyComplete,
    excluded_by: excludedBy,
    reconciliation_status: reconciliationStatus,
    include_review: includeReview,
    ready,
    reviewable,
    accounted
  });

  if (excludedBy) continue;

  out.push({
    airtable_record_id: rec.id,
    sales_channel: salesChannel,
    external_order_id: f.external_order_id || f.ecwid_order_id || null,
    order_ref: String(f.order_code || f.external_order_id || f.ecwid_order_id || f.order_number || ''),
    order_number: f.order_number || null,
    order_date: f.order_date || null,
    order_date_local: localDateTime(f.order_date, timezone),
    order_date_local_date: rowDate,
    customer_name: f.customer_name || '',
    payment_method: paymentMethod,
    payment_status: f.payment_status || '',
    payment_processor: paymentProcessor,
    payment_reconciliation_status: reconciliationStatus,
    processor_payment_id: processorPaymentId,
    processor_payment_status: processorPaymentStatus,
    processor_payment_amount: processorPaymentAmount,
    processor_payment_time: processorPaymentTime,
    processor_match_confidence: processorMatchConfidence,
    // Legacy Clover status is retained in the response while Appsmith and
    // downstream callers migrate to payment_reconciliation_status.
    clover_reconciliation_status: f.clover_reconciliation_status || '',
    payment_state: market
      ? (reconciliationStatus || 'pending')
      : (f.payment_status || ''),
    needs_reconciliation_review: requiresProcessorReconciliation && !ready,
    reviewable,
    accounted,
    mode: market ? 'market' : 'web',
    linked_count: linkedCount,
    required_count: requiredCount,
    product_assignment_complete: productAssignmentComplete,
    reconciliation_complete: reconciliationComplete,
    assignment_complete_needs_reconciliation: assignmentCompleteNeedsReconciliation,
    fully_complete: fullyComplete,
    can_assign_products: !productAssignmentComplete,
    cash_web_order: cashWeb,
    cash_payment_received: paymentStatus === "PAID",
    fulfillment_progress: progress,
    can_reconcile: requiresProcessorReconciliation && !reconciliationComplete,
    product_names: itemSummary(items) || '(none)',
    products_report: f.products_report || '',
    product_ids_report: f.product_ids_report || '',
    items,
    reconciliation_notes: f.reconciliation_notes || ''
  });
}

out.sort((a, b) => String(b.order_date || '').localeCompare(String(a.order_date || '')));

return [{
  json: {
    ok: true,
    req: {
      ...req,
      date_raw: reqDateRaw,
      date: reqDate,
      timezone
    },
    orders: out,
    count: out.length,
    debug
  }
}];

const f=$json.fields||{}; function parseItems(s){ try{ const a=typeof s==='string'?JSON.parse(s):[]; return Array.isArray(a)?a:[];}catch(e){return [];} }
const items=parseItems(f.items_json).map((i,idx)=>({line_index:idx+1,name:i.name||i.nameTranslated?.en||'(unknown)',sku:i.sku||'',productId:i.productId||null,quantity:Number(i.quantity||0)||0}));
const progress=f.fulfillment_progress||{};
const linked=Array.isArray(f.products)?f.products:[];
const channel=String(f.provider||'ecwid').trim()||'ecwid'; const summary=`${channel.toUpperCase()} ${String(f.order_code||f.external_order_id||f.ecwid_order_id||f.order_number||'')} | ${f.customer_name||''} | linked ${linked.length} of ${items.reduce((n,i)=>n+i.quantity,0)} required`;
return [{json:{ok:true, airtable_record_id:$json.id, order_ref:String(f.order_code||f.ecwid_order_id||f.order_number||''), summary, items:progress.items||items, progress, linked_products:linked, products_report:f.products_report||'', product_ids_report:f.product_ids_report||'', raw_fields:f}}];

const b=$json.body||$json;
const page=Number(b.page||1), size=Number(b.page_size||25);
if(!Number.isSafeInteger(page)||page<1||page>100000||!Number.isSafeInteger(size)||size<1||size>100) throw new Error('Invalid product page');
return [{json:{order_id:String(b.airtable_order_record_id||''),query:String(b.query||'').trim(),page,page_size:size,line_id:String(b.line_id||'')}}];

const b=$json.body||$json;
if(!b.airtable_order_record_id||!b.airtable_product_record_id||!b.operator) throw new Error('Order, product and operator required');
return [{json:{order_id:String(b.airtable_order_record_id),product_id:String(b.airtable_product_record_id),operator:String(b.operator),line_id:String(b.line_id||'')}}];

if (String(($json.body||$json).payment_processor||'').toLowerCase()==='cash') throw new Error('Record actual cash received through the protected receipt action');
const body = $json.body || $json;
const id = String(body.airtable_order_record_id || body.airtable_record_id || '').trim();
const processor = String(body.payment_processor || body.processor || 'clover').trim().toLowerCase() || 'clover';
const paymentId = String(body.processor_payment_id || body.clover_payment_id || '').trim();
if (!id) throw new Error('Missing airtable_order_record_id');
if (!paymentId) throw new Error('Missing processor_payment_id');

const amountRaw = body.processor_payment_amount ?? body.clover_payment_amount;
const amount = amountRaw === undefined || amountRaw === null || amountRaw === ''
  ? null
  : Number(amountRaw);
if (amount !== null && !Number.isFinite(amount)) throw new Error('Invalid processor_payment_amount');

function isoOrNull(v) {
  if (!v) return null;
  const d = new Date(v);
  if (!Number.isFinite(d.getTime())) throw new Error('Invalid processor_payment_time');
  return d.toISOString();
}

const paymentTime = isoOrNull(body.processor_payment_time || body.clover_payment_time);
const processorOrderId = String(body.processor_order_id || body.clover_order_id || '').trim();
const tenderId = String(body.processor_tender_id || body.clover_tender_id || '').trim();
const operator = String(body.operator || 'system').trim() || 'system';
const note = String(body.note || `Manually matched ${processor} payment in Appsmith.`).trim();
const nowIso = new Date().toISOString();
const isClover = processor === 'clover';

return [{
  json: {
    airtable_order_record_id: id,
    result: {
      ok: true,
      airtable_order_record_id: id,
      reconciliation_status: 'reconciled',
      payment_processor: processor,
      processor_payment_id: paymentId,
      clover_payment_id: isClover ? paymentId : null,
      message: `Order manually reconciled to ${processor} payment.`
    },
    fields: {
      payment_processor: processor,
      payment_reconciliation_status: 'reconciled',
      processor_payment_id: paymentId,
      processor_payment_status: 'succeeded',
      processor_payment_amount: amount,
      processor_payment_time: paymentTime,
      processor_match_confidence: 0.5,
      // Clover aliases remain dual-written only for Clover. Explicit non-Clover
      // reconciliation clears stale legacy values so they cannot masquerade as
      // current processor state.
      clover_reconciliation_status: isClover ? 'reconciled' : null,
      clover_payment_id: isClover ? paymentId : null,
      clover_payment_amount: isClover ? amount : null,
      clover_payment_time: isClover ? paymentTime : null,
      clover_match_confidence: isClover ? 0.5 : null,
      reconciled_at: nowIso,
      reconciliation_notes: [
        note,
        'Manually reconciled by operator.',
        processorOrderId ? `${processor} order id: ${processorOrderId}` : null,
        tenderId ? `Tender id: ${tenderId}` : null,
        `Operator: ${operator}`
      ].filter(Boolean).join(' | ')
    }
  }
}];
